-- Seed do plano de 365 dias do Ano Biblico (gerado por scripts/gerar_seed_ano_biblico.py a partir do PDF fornecido pelo usuario).
-- Nao editar a mao: rode o script novamente e substitua este arquivo.

ON CONFLICT (mes, dia, ano_bissexto) DO UPDATE SET
  ordem_no_ano = EXCLUDED.ordem_no_ano,
  livro_abrev = EXCLUDED.livro_abrev,
  livro_nome = EXCLUDED.livro_nome,
  referencia = EXCLUDED.referencia,
  passagens = EXCLUDED.passagens,
  updated_at = now();
